"""Regenerate the standalone guide after editing data.json. No external packages."""
import json
from hashlib import sha256
from pathlib import Path
from html import escape as e
from urllib.parse import urlencode
ROOT=Path(__file__).resolve().parent
data=json.loads((ROOT/'data.json').read_text());venues=data['venues']
def asset(path):
 version=sha256((ROOT/path).read_bytes()).hexdigest()[:12]
 return f'{path}?v={version}'
def link(url,label,cls=''):
 return f'<a class="{cls}" href="{e(url,quote=True)}" target="_blank" rel="noopener noreferrer">{label} ↗</a>'
def img(stem,alt,extra=''):
 suffix=next((ext for ext in ("webp","png","jpg") if (ROOT/"images"/f"{stem}.{ext}").exists()), "webp")
 return f'<img src="images/{stem}.{suffix}" alt="{e(alt)}" width="1200" height="800" loading="lazy" decoding="async" {extra}>'
def gallery(v,key):
 if not v['photos']:
  return '<div class="gallery photo-unavailable"><p>Venue photos unavailable.<br>See the venue link below for more.</p></div>'
 photo_sources=' · '.join(link(url,e(label)) for url,label in v.get('photoSources',[[v['url'],v['name']]]))
 slides=''.join(f'<figure class="slide" id="photo-{key}-{i}">{img(stem,alt)}<figcaption>{e(alt)}</figcaption></figure>' for i,(stem,alt) in enumerate(v['photos']))
 return f'''<div class="gallery" aria-label="{e(v['name'])} photo gallery"><div class="slides" tabindex="0" aria-label="Photos: scroll horizontally or use arrow buttons">{slides}</div><div class="gallery-controls"><span class="counter" aria-live="polite">1 / {len(v['photos'])}</span><span>Photos: {photo_sources}</span><div class="gallery-buttons" hidden><button type="button" data-step="-1" aria-label="Previous photo of {e(v['name'])}">←</button><button type="button" data-step="1" aria-label="Next photo of {e(v['name'])}">→</button></div></div></div>'''
def venue(key,number):
 v=venues[key]
 maps='https://www.google.com/maps/search/?'+urlencode({'api':1,'query':v['name']+', '+v['address']+', Amsterdam'})
 return f'''<section class="venue"><div class="stop-label"><span>{number}</span> {'FIRST, A DRINK' if number=='A' else 'THEN, DINNER'}</div>{gallery(v,key)}<div class="venue-heading"><h3>{e(v['name'])}</h3><span class="tier">{v['tier']}</span></div><p class="category">{e(v['kind'])} <span>·</span> {e(v['address'])}</p><p>{e(v['description'])}</p><dl><div><dt>Budget</dt><dd>{e(v['price'])}<small>{e(v['budget'])}</small></dd></div><div><dt>Friday</dt><dd>{e(v['hours'])}</dd></div></dl><p class="booking">{e(v['note'])}</p><div class="venue-links">{link(v['url'],'Visit / booking')}{link(v['menu'],'Menu & details')}{link(maps,'Google Maps')}</div></section>'''
def pairing_photo(stem,caption):
 if not stem:
  return f'<figure class="photo-unavailable"><p>{e(caption)}</p></figure>'
 return f'<figure>{img(stem,caption)}<figcaption>{e(caption)}</figcaption></figure>'
count=len(data['pairs'])
quick=[];cards=[]
for i,p in enumerate(data['pairs'],1):
 b=venues[p['bar']];r=venues[p['restaurant']];price=f"€{p['cost'][0]}–{p['cost'][1]}";score=round(sum(a*w for a,w in zip(p['scores'],[.45,.35,.20]))*10)
 route='https://www.google.com/maps/dir/?'+urlencode({'api':1,'origin':b['name']+', '+b['address']+', Amsterdam','destination':r['name']+', '+r['address']+', Amsterdam','travelmode':'walking'})
 quick.append(f'''<a class="quick-card" href="#{p['id']}"><span class="mini-number">0{i} / {e(p['label'])}</span><strong>{e(b['name'])}<span> + {e(r['name'])}</span></strong><span class="quick-facts">{price} pp <span>·</span> {p['walk']} walk <span>↘</span></span></a>''')
 cards.append(f'''<article class="pair" id="{p['id']}" data-cost="{p['cost'][0]}" data-walk="{p['minutes']}" data-rank="{i}"><header class="pair-header"><div class="pair-number">0{i}</div><div><p class="eyebrow">{e(p['label'])} <span> / </span> {e(p['area'])}</p><h2>{e(p['title'])}</h2></div><button type="button" class="share" data-share="{p['id']}" hidden aria-label="Copy link to {e(b['name'])} and {e(r['name'])}">Copy this plan ↗</button></header><div class="pair-intro"><p>{e(p['reason'])}</p><div class="pair-facts"><div><strong>{price}</strong><span>per person, estimated</span></div><div><strong>{p['walk']}</strong><span>walk · {p['distance']}</span></div></div></div><div class="venues">{venue(p['bar'],'A')}{venue(p['restaurant'],'B')}</div><div class="evening"><div class="flavours"><p class="eyebrow">A LITTLE ORDER INSPIRATION</p><h3>{e(p['drink'])} <span>→</span><br>{e(p['dish'])}</h3><div class="pairing-photos">{pairing_photo(p['drinkPhoto'],p['drinkCaption'])}{pairing_photo(p['dishPhoto'],p['dishCaption'])}</div><p>{e(p['pairing'])}</p><p class="small">{e(p['orderNote'])} These are our suggestions for successive stops, not a venue pairing menu.</p></div><div class="route"><p class="eyebrow">YOUR EVENING, ON FOOT</p><ol class="schedule"><li><time>{p['start']}</time><span>{e(b['name'])}</span></li><li><span class="walk-icon">↳</span><span>{p['walk']} walk, estimated</span></li><li><time>{p['dinner']}</time><span>{e(r['name'])}</span></li></ol><div class="map" id="map-{p['id']}" data-bar="{p['bar']}" data-restaurant="{p['restaurant']}" role="region" aria-label="Map of {e(b['name'])} and {e(r['name'])}"><p class="map-fallback">A · {e(b['address'])}<br>B · {e(r['address'])}<br>{link(route,'Open both stops in walking directions')}</p></div><p class="map-key"><span>A</span> Drinks <span class="restaurant-pin">B</span> Dinner · pins show locations, not a plotted route.</p>{link(route,'Open walking directions','route-link')}</div></div><div class="tradeoff"><span>GOOD TO KNOW</span><p>{e(p['tradeoff'])}</p></div><details class="fit-details"><summary>Why this pairing? <span>{score}/100 editorial fit</span></summary><p>Our judgement, not a customer rating: atmosphere & food fit 45% ({p['scores'][0]}/10), value 35% ({p['scores'][1]}/10), walking convenience 20% ({p['scores'][2]}/10). Friday opening and a workable dinner schedule are prerequisites. Approximate walks allow for street crossings; check live directions before setting off.</p></details></article>''')
sources=''.join(f'<li><strong>{e(v["name"])}</strong> — {link(v["url"],"official hours, booking & photos")} · {link(v["menu"],"menu")}</li>' for v in venues.values())
html=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>30 October · Drinks, then dinner · Amsterdam</title><meta name="description" content="{count} thoughtful cocktail-bar and restaurant pairings for five friends in Amsterdam on Friday 30 October 2026. Photos, budgets, walking maps and booking notes."><meta name="theme-color" content="#702e3c"><link rel="stylesheet" href="{asset('styles.css')}"><link rel="stylesheet" href="{asset('vendor/leaflet.css')}"><script src="{asset('vendor/leaflet.js')}" defer></script><script src="{asset('app.js')}" defer></script></head><body><a class="skip" href="#plans">Skip to the plans</a><header class="masthead"><a href="/" class="wordmark">An evening in Amsterdam<span>A LITTLE GUIDE FOR FIVE FRIENDS</span></a><a href="#shortlist">The shortlist <span>↘</span></a></header><main><section class="hero"><div class="hero-copy"><p class="eyebrow"><span class="dot"></span> FRIDAY, 30 OCTOBER 2026</p><h1>Good drinks.<br>Better company.</h1><p class="dek">One cocktail bar. One lovely dinner.<br>Five friends, and nowhere to rush.</p><p class="hero-note">{count} ways to spend a Friday, from the centre to the Jordaan, De Pijp and Museumkwartier.</p><a href="#shortlist" class="primary-link">Find our evening <span>↓</span></a></div><div class="hero-art"><figure class="hero-main">{img('oldenhof-room','Warm lights and dark wood at Bar Oldenhof','fetchpriority="high"')}</figure><figure class="hero-small">{img('janine-10','Wood-fired pizza at Janine')}<figcaption>Stay for dinner.</figcaption></figure><div class="date-stamp" aria-label="30 October, five people"><strong>30</strong><span>OCTOBER</span><i>table for five</i></div></div></section><div class="context-strip"><span>Centrum & nearby neighbourhoods</span><span>{count} paired evenings</span><span>2–30 minute walks</span><span>Friday planning notes</span></div><section id="shortlist" class="shortlist"><div class="section-heading"><div><p class="eyebrow">LESS GROUP-CHAT SCROLLING</p><h2>Pick the kind of night.</h2></div><p>Seven plans fit published Friday hours; Esh needs confirmation.<br>Choose a mood, then check a table for five.</p></div><div class="quick-grid">{''.join(quick)}</div><div class="budget-note"><strong>What the prices mean</strong><p>Totals cover <b>one cocktail + dinner food per person</b>. Add dinner drinks, extra rounds and any tip. At bars: € up to €12, €€ €13–18, €€€ €19+. At restaurants: € up to €30, €€ €31–50, €€€ €51+ for food. Ranges cross bands. These are planning estimates, not fixed-price packages.</p></div></section><section id="plans"><div class="plans-heading"><h2>The evenings</h2><label class="sort-control" hidden>Show first <select id="sort"><option value="rank">Our recommended order</option><option value="cost">Lowest starting budget</option><option value="walk">Shortest walk</option></select></label></div><div id="pair-list">{''.join(cards)}</div></section><section class="before"><div><p class="eyebrow">BEFORE THE GROUP SAYS “BOOK IT”</p><h2>A small bit of planning.</h2></div><div><p><strong>Friday hours checked, tables not booked.</strong> Researched {data['checked']} using the venues’ published schedules. All venues except Esh list Friday service covering these suggested times. Esh’s reported hours come from editorial listings; confirm its dinner service directly. Specific availability for 30 October, private events and last-minute changes still need confirmation.</p><p>Choose a plan, check dinner for five, then check the bar’s booking or walk-in policy. Ask about dietary needs before reserving. Suggested arrival times are a plan, not a reservation.</p><p>Fitz’s sets the mood for this guide, but its location in Oost stretches the city-centre brief. Oldenhof is the closest cosy alternative here. Stacks, KID, Pendergast and Morgan & Mees extend the shortlist west of Centrum; Bar Mokum and Esh add a southern option. The Pendergast and Dutch Courage–Tujuh Maret plans exceed the original 20-minute walking brief.</p></div></section><details class="sources"><summary>Sources, photo credits & how this was put together</summary><p>Venue pages and menus researched on {data['checked']}. Photos come from venues, editorial coverage and design portfolios, credited beneath each gallery; original image URLs are recorded in {link('images/credits.json','the photo source list')}. They show the venues and their food or drinks, not a guarantee of the exact item served on the night.</p><ul>{sources}</ul><p>Walking times and distances are editorial estimates, not live routing. Map address points use {link('https://www.pdok.nl/introductie/-/article/locatieserver','PDOK')} where available; the Super Lyan, KID and Pendergast pins are approximate. Esh’s official site was unavailable; its {link('https://www.debuik.nl/amsterdam/restaurant/esh-pitaria-bar','De Buik listing')} and {link('https://www.restauplant.com/nl/restaurant/esh-pitaria-bar','RestauPlant listing')} support the provisional dinner option. Its current menu, kitchen hours and prices remain unverified. Esh food photos come from Raphael Meibergen’s 2024 De Buik coverage; its interior is shown in Studio Michiel Wijnen’s project portfolio. KID food photos come from Amsterdam NOW’s coverage of the Frederik Hendrikplantsoen location. Base maps © OpenStreetMap contributors.</p></details></main><footer><span>30 October 2026 · Amsterdam · Five friends</span><a href="#">Back to the top ↑</a></footer><div id="notice" role="status" aria-live="polite"></div><script type="application/json" id="venue-data">{json.dumps({k: {'name':v['name'],'coords':v['coords']} for k,v in venues.items()})}</script></body></html>'''
# The lead image loads eagerly; other images remain lazy.
html=html.replace('loading="lazy" decoding="async" fetchpriority="high"','loading="eager" decoding="async" fetchpriority="high"')
(ROOT/'index.html').write_text(html)
print('Built',ROOT/'index.html')
